/* ============================================================
   OpenLearnHub - Shared Styles
   ============================================================ */

/* --- Google Fonts --- */
@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

/* --- CSS Variables --- */
:root {
  --primary: #0A0A23;
  --primary-light: #1a1a3e;
  --accent: #FEAC32;
  --accent-hover: #e5981a;
  --accent-light: #fff3d6;
  --link-blue: #002EAD;
  --bg-white: #ffffff;
  --bg-light: #f8f9fa;
  --bg-cream: #fefaf3;
  --text-primary: #1a1a2e;
  --text-secondary: #555770;
  --text-muted: #8e8ea0;
  --border: #e2e4e9;
  --border-light: #f0f0f5;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --font-display: 'Space Grotesk', system-ui, sans-serif;
  --font-body: 'Plus Jakarta Sans', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
  --max-width: 1200px;
  --header-height: 64px;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background-color: var(--bg-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: var(--link-blue);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--accent);
}

ul, ol {
  list-style: none;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  font-weight: 700;
  line-height: 1.2;
  color: var(--primary);
}

h1 { font-size: clamp(2rem, 5vw, 3rem); }
h2 { font-size: clamp(1.5rem, 4vw, 2.25rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.5rem); }

.section-title {
  font-family: var(--font-display);
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary);
  margin-bottom: 1.5rem;
}

.section-subtitle {
  font-size: 1.05rem;
  color: var(--text-secondary);
  margin-bottom: 2rem;
}

/* ============================================================
   HEADER & NAVIGATION
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--primary);
  border-bottom: 2px solid rgba(254, 172, 50, 0.15);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--header-height);
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 700;
  color: #ffffff;
  letter-spacing: -0.02em;
  white-space: nowrap;
}

.logo:hover {
  color: var(--accent);
}

.logo-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  background: var(--accent);
  color: var(--primary);
  border-radius: var(--radius-sm);
  font-family: var(--font-display);
  font-size: 0.85rem;
  font-weight: 800;
  flex-shrink: 0;
}

.search-bar {
  display: flex;
  align-items: center;
  flex: 0 1 420px;
  margin: 0 24px;
}

.search-bar input {
  width: 100%;
  padding: 9px 16px;
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: 20px;
  background: rgba(255,255,255,0.08);
  color: #ffffff;
  font-family: var(--font-body);
  font-size: 0.875rem;
  outline: none;
  transition: all 0.2s ease;
}

.search-bar input::placeholder {
  color: rgba(255,255,255,0.45);
}

.search-bar input:focus {
  border-color: var(--accent);
  background: rgba(255,255,255,0.12);
}

.header-nav {
  display: flex;
  align-items: center;
  gap: 4px;
}

.header-nav a {
  padding: 8px 16px;
  color: rgba(255,255,255,0.8);
  font-size: 0.9rem;
  font-weight: 500;
  border-radius: var(--radius-sm);
  transition: all 0.2s ease;
}

.header-nav a:hover {
  color: #ffffff;
  background: rgba(255,255,255,0.08);
}

.header-nav a.nav-donate {
  background: var(--accent);
  color: var(--primary);
  font-weight: 600;
  padding: 8px 18px;
}

.header-nav a.nav-donate:hover {
  background: var(--accent-hover);
  color: var(--primary);
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
  z-index: 1001;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: #ffffff;
  border-radius: 2px;
  transition: all 0.3s ease;
}

.hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
}

.hamburger.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile Nav */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--primary);
  z-index: 999;
  padding: 32px 24px;
  flex-direction: column;
  gap: 8px;
}

.mobile-nav.active {
  display: flex;
}

.mobile-nav a {
  display: block;
  padding: 14px 20px;
  color: rgba(255,255,255,0.85);
  font-size: 1.1rem;
  font-weight: 500;
  border-radius: var(--radius-sm);
  transition: all 0.2s ease;
}

.mobile-nav a:hover {
  color: #ffffff;
  background: rgba(255,255,255,0.08);
}

.mobile-nav a.nav-donate {
  background: var(--accent);
  color: var(--primary);
  font-weight: 600;
  text-align: center;
  margin-top: 8px;
}

/* ============================================================
   BANNER
   ============================================================ */
.banner {
  background: linear-gradient(135deg, var(--accent) 0%, #f5a623 50%, #e5981a 100%);
  color: var(--primary);
  text-align: center;
  padding: 12px 24px;
  font-size: 0.95rem;
  font-weight: 600;
  font-family: var(--font-display);
  letter-spacing: 0.01em;
}

.banner a {
  color: var(--primary);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.banner a:hover {
  color: var(--primary);
  text-decoration-thickness: 2px;
}

/* ============================================================
   FEATURED ARTICLE
   ============================================================ */
.featured-article {
  padding: 48px 0 32px;
}

.featured-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg-white);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-md);
  transition: box-shadow 0.3s ease, transform 0.3s ease;
}

.featured-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.featured-thumb {
  position: relative;
  background: linear-gradient(135deg, #1a1a3e 0%, #2d1b69 50%, #1a1a3e 100%);
  min-height: 280px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.featured-thumb::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 20% 30%, rgba(254, 172, 50, 0.15) 0%, transparent 50%),
    radial-gradient(circle at 80% 70%, rgba(0, 46, 173, 0.2) 0%, transparent 50%);
}

.featured-thumb-pattern {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  color: rgba(254, 172, 50, 0.4);
  line-height: 1.8;
  position: relative;
  z-index: 1;
}

.featured-tag-label {
  position: absolute;
  top: 20px;
  left: 20px;
  z-index: 2;
}

.featured-content {
  padding: 36px 32px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.featured-content .post-tag {
  margin-bottom: 12px;
}

.featured-content h2 {
  font-size: clamp(1.35rem, 3vw, 1.75rem);
  margin-bottom: 16px;
  line-height: 1.3;
}

.featured-content h2 a {
  color: var(--primary);
}

.featured-content h2 a:hover {
  color: var(--link-blue);
}

/* ============================================================
   ARTICLE CARDS & GRID
   ============================================================ */
.articles-section {
  padding: 24px 0 56px;
}

.articles-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.article-card {
  background: var(--bg-white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: all 0.3s ease;
  display: flex;
  flex-direction: column;
}

.article-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
  border-color: var(--border-light);
}

.card-thumb {
  position: relative;
  height: 180px;
  overflow: hidden;
}

.card-thumb-bg {
  width: 100%;
  height: 100%;
}

.thumb-ai {
  background: linear-gradient(135deg, #1a1a3e, #2d1b69);
  position: relative;
}

.thumb-ai::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 70% 30%, rgba(138, 43, 226, 0.3), transparent 60%);
}

.thumb-scraping {
  background: linear-gradient(135deg, #0d2818, #1a4a2e);
  position: relative;
}

.thumb-scraping::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 70%, rgba(0, 200, 100, 0.2), transparent 60%);
}

.thumb-databases {
  background: linear-gradient(135deg, #1a1a2e, #2d2d44);
  position: relative;
}

.thumb-databases::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 60% 40%, rgba(254, 172, 50, 0.2), transparent 60%);
}

.thumb-elasticsearch {
  background: linear-gradient(135deg, #1a1a2e, #1e3a5f);
  position: relative;
}

.thumb-elasticsearch::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 40% 60%, rgba(0, 210, 210, 0.2), transparent 60%);
}

.thumb-data {
  background: linear-gradient(135deg, #0a1628, #1a3050);
  position: relative;
}

.thumb-data::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 50%, rgba(0, 150, 255, 0.2), transparent 60%);
}

.thumb-default {
  background: linear-gradient(135deg, #1a1a3e, #2a2a4a);
  position: relative;
}

.thumb-default::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 50%, rgba(254, 172, 50, 0.15), transparent 60%);
}

.card-tag-label {
  position: absolute;
  top: 12px;
  left: 12px;
}

.card-body {
  padding: 20px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.card-body h3 {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 16px;
  line-height: 1.4;
  flex: 1;
}

.card-body h3 a {
  color: var(--primary);
}

.card-body h3 a:hover {
  color: var(--link-blue);
}

.card-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-top: 16px;
  border-top: 1px solid var(--border-light);
}

.author-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--primary-light);
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 0.75rem;
  font-weight: 600;
  flex-shrink: 0;
}

.avatar-ms { background: #6c5ce7; }
.avatar-jo { background: #00b894; }
.avatar-iy { background: #e17055; }
.avatar-ol { background: #0984e3; }
.avatar-ps { background: #fd79a8; }
.avatar-rp { background: #636e72; }
.avatar-ot { background: #fdcb6e; color: var(--primary); }
.avatar-sc { background: #a29bfe; }
.avatar-mr { background: #55a3e8; }
.avatar-dk { background: #e056a0; }
.avatar-ew { background: #00cec9; }
.avatar-at { background: #fab1a0; }

.card-meta-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.card-author {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-primary);
}

.card-time {
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* Post Tag Labels */
.post-tag {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 20px;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  line-height: 1.4;
}

.tag-ai { background: #f0e6ff; color: #6c2bd9; }
.tag-web-scraping { background: #e6f7ee; color: #0d7d44; }
.tag-databases { background: #fff0e0; color: #c7510a; }
.tag-elasticsearch { background: #e0f7fa; color: #007c91; }
.tag-data-engineering { background: #e0f0ff; color: #0059b3; }
.tag-javascript { background: #fff9e0; color: #9a7b0c; }
.tag-python { background: #e8f0fe; color: #1a56c4; }
.tag-react { background: #e0f7fa; color: #007c91; }
.tag-css { background: #fde8f0; color: #c02660; }
.tag-devops { background: #fff0e0; color: #c7510a; }
.tag-node { background: #e6f7ee; color: #0d7d44; }
.tag-google-sheets { background: #e6f7ee; color: #0d7d44; }

/* ============================================================
   LOAD MORE
   ============================================================ */
.load-more-wrap {
  text-align: center;
  padding: 24px 0 48px;
}

.btn-load-more {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 32px;
  background: var(--primary);
  color: #ffffff;
  border: none;
  border-radius: var(--radius-sm);
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
}

.btn-load-more:hover {
  background: var(--primary-light);
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

.btn-load-more:active {
  transform: translateY(0);
}

/* ============================================================
   TAG PAGE
   ============================================================ */
.tag-page-header {
  padding: 40px 0 16px;
}

.tag-name {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 1rem;
  font-weight: 600;
  padding: 6px 16px;
  border-radius: 20px;
  margin-bottom: 8px;
}

.tag-post-count {
  font-size: 1.05rem;
  color: var(--text-secondary);
  margin-bottom: 24px;
}

/* Popular Tags Bar */
.popular-tags-section {
  padding: 16px 0 32px;
}

.popular-tags-label {
  font-family: var(--font-display);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 12px;
}

.popular-tags-scroll {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 8px;
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
  -webkit-overflow-scrolling: touch;
}

.popular-tags-scroll::-webkit-scrollbar {
  height: 4px;
}

.popular-tags-scroll::-webkit-scrollbar-track {
  background: transparent;
}

.popular-tags-scroll::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 4px;
}

.tag-pill {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  background: var(--bg-light);
  border: 1px solid var(--border);
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-primary);
  white-space: nowrap;
  transition: all 0.2s ease;
  cursor: pointer;
  flex-shrink: 0;
}

.tag-pill:hover {
  background: var(--primary);
  color: #ffffff;
  border-color: var(--primary);
}

.tag-pill-count {
  font-weight: 600;
  color: var(--text-muted);
  font-size: 0.78rem;
}

.tag-pill:hover .tag-pill-count {
  color: rgba(255,255,255,0.7);
}

/* ============================================================
   LEARN PAGE
   ============================================================ */
.learn-hero {
  background: linear-gradient(135deg, var(--primary) 0%, #1a1a40 100%);
  padding: 48px 0;
  text-align: center;
  color: #ffffff;
}

.learn-hero h1 {
  color: #ffffff;
  margin-bottom: 12px;
}

.learn-hero p {
  color: rgba(255,255,255,0.75);
  font-size: 1.1rem;
  max-width: 600px;
  margin: 0 auto 24px;
}

.btn-sign-in {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 28px;
  background: var(--accent);
  color: var(--primary);
  border: none;
  border-radius: var(--radius-sm);
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
}

.btn-sign-in:hover {
  background: var(--accent-hover);
  transform: translateY(-1px);
}

/* Curriculum Grid */
.curriculum-section {
  padding: 56px 0;
}

.curriculum-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.curriculum-card {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 20px 24px;
  background: var(--bg-white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  transition: all 0.3s ease;
}

.curriculum-card:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.curriculum-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}

.ci-web { background: #e8f0fe; color: #1a56c4; }
.ci-js { background: #fff9e0; color: #9a7b0c; }
.ci-fe { background: #e0f7fa; color: #007c91; }
.ci-py { background: #e8f0fe; color: #1a56c4; }
.ci-db { background: #fff0e0; color: #c7510a; }
.ci-be { background: #f0e6ff; color: #6c2bd9; }
.ci-fs { background: linear-gradient(135deg, #e8f0fe, #f0e6ff); color: #1a1a3e; }

.curriculum-info h4 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 4px;
}

.curriculum-info p {
  font-size: 0.85rem;
  color: var(--text-muted);
}

/* Daily Challenge */
.daily-challenge {
  background: linear-gradient(135deg, #fefaf3 0%, #fff8e7 100%);
  border: 1px solid rgba(254, 172, 50, 0.2);
  border-radius: var(--radius-lg);
  padding: 32px;
  margin: 40px 0;
  text-align: center;
}

.daily-challenge h3 {
  color: var(--primary);
  margin-bottom: 8px;
}

.daily-challenge p {
  color: var(--text-secondary);
  margin-bottom: 20px;
}

.daily-challenge-links {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn-challenge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 24px;
  border-radius: var(--radius-sm);
  font-family: var(--font-display);
  font-size: 0.9rem;
  font-weight: 600;
  transition: all 0.3s ease;
  cursor: pointer;
}

.btn-challenge-primary {
  background: var(--accent);
  color: var(--primary);
  border: none;
}

.btn-challenge-primary:hover {
  background: var(--accent-hover);
}

.btn-challenge-secondary {
  background: transparent;
  color: var(--primary);
  border: 1px solid var(--primary);
}

.btn-challenge-secondary:hover {
  background: var(--primary);
  color: #ffffff;
}

/* Resource Sections */
.resource-section {
  padding: 32px 0;
}

.resource-section h3 {
  font-size: 1.35rem;
  margin-bottom: 16px;
}

.resource-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.resource-list li {
  padding: 12px 16px;
  background: var(--bg-light);
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  color: var(--text-primary);
  transition: all 0.2s ease;
  border: 1px solid transparent;
}

.resource-list li:hover {
  border-color: var(--border);
  background: var(--bg-white);
}

.resource-list li a {
  color: var(--primary);
  font-weight: 500;
}

.resource-list li a:hover {
  color: var(--link-blue);
}

/* ============================================================
   DONATE PAGE
   ============================================================ */
.donate-hero {
  padding: 64px 0 40px;
  text-align: center;
}

.donate-hero h1 {
  margin-bottom: 16px;
}

.donate-hero .hero-description {
  max-width: 700px;
  margin: 0 auto 32px;
  color: var(--text-secondary);
  font-size: 1.1rem;
  line-height: 1.7;
}

/* Donation Card */
.donation-card {
  max-width: 540px;
  margin: 0 auto 56px;
  background: var(--bg-white);
  border: 2px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 36px 32px;
  box-shadow: var(--shadow-md);
}

.donation-amounts {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin-bottom: 20px;
}

.donation-amount-btn {
  padding: 14px 8px;
  background: var(--bg-light);
  border: 2px solid var(--border);
  border-radius: var(--radius-sm);
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-primary);
  cursor: pointer;
  transition: all 0.25s ease;
}

.donation-amount-btn:hover {
  border-color: var(--accent);
  background: var(--accent-light);
}

.donation-amount-btn.active {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--primary);
  box-shadow: 0 2px 12px rgba(254, 172, 50, 0.35);
}

.donation-description {
  text-align: center;
  font-size: 0.95rem;
  color: var(--text-secondary);
  margin-bottom: 20px;
  padding: 16px;
  background: var(--bg-cream);
  border-radius: var(--radius-sm);
  line-height: 1.6;
  transition: all 0.3s ease;
}

.btn-donate {
  display: block;
  width: 100%;
  padding: 14px;
  background: var(--accent);
  color: var(--primary);
  border: none;
  border-radius: var(--radius-sm);
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.3s ease;
  margin-bottom: 12px;
}

.btn-donate:hover {
  background: var(--accent-hover);
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

.donation-sub-label {
  text-align: center;
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* Supporter Benefits */
.benefits-section {
  padding: 48px 0;
}

.benefits-section h2 {
  text-align: center;
  margin-bottom: 32px;
}

.benefits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 20px;
}

.benefit-card {
  padding: 24px;
  background: var(--bg-white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  text-align: center;
  transition: all 0.3s ease;
}

.benefit-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.benefit-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 16px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.35rem;
}

.bi-badge {
  background: #fff3d6;
}

.bi-halo {
  background: linear-gradient(135deg, #fff3d6, #ffe0a0);
}

.bi-discord {
  background: #e8e9ff;
}

.bi-popup {
  background: #e6f7ee;
}

.bi-more {
  background: #f0f0f8;
}

.benefit-card h4 {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--primary);
}

/* Initiatives & Achievements */
.initiatives-section,
.achievements-section {
  padding: 32px 0 48px;
}

.initiatives-section h2,
.achievements-section h2 {
  text-align: center;
  margin-bottom: 32px;
}

.initiatives-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 16px;
}

.initiative-item {
  padding: 20px 24px;
  background: var(--bg-white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 12px;
  transition: all 0.3s ease;
}

.initiative-item:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow-sm);
}

.initiative-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
  flex-shrink: 0;
}

.achievements-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 20px;
}

.achievement-card {
  padding: 28px 20px;
  background: var(--bg-white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  text-align: center;
  transition: all 0.3s ease;
}

.achievement-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.achievement-number {
  font-family: var(--font-display);
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--accent);
  margin-bottom: 8px;
}

.achievement-label {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.4;
}

/* ============================================================
   FAQ ACCORDION
   ============================================================ */
.faq-section {
  padding: 32px 0 64px;
}

.faq-section h2 {
  text-align: center;
  margin-bottom: 32px;
}

.faq-list {
  max-width: 760px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.faq-item {
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  overflow: hidden;
  transition: all 0.2s ease;
}

.faq-item:hover {
  border-color: var(--border);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 18px 20px;
  background: var(--bg-white);
  border: none;
  cursor: pointer;
  font-family: var(--font-body);
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-primary);
  text-align: left;
  transition: all 0.2s ease;
}

.faq-question:hover {
  background: var(--bg-light);
}

.faq-icon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  position: relative;
  transition: transform 0.3s ease;
}

.faq-icon::before,
.faq-icon::after {
  content: '';
  position: absolute;
  background: var(--text-muted);
  transition: all 0.3s ease;
}

.faq-icon::before {
  top: 11px;
  left: 4px;
  right: 4px;
  height: 2px;
}

.faq-icon::after {
  left: 11px;
  top: 4px;
  bottom: 4px;
  width: 2px;
}

.faq-item.active .faq-icon::after {
  transform: rotate(90deg);
  opacity: 0;
}

.faq-item.active .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}

.faq-item.active .faq-answer {
  max-height: 300px;
}

.faq-answer-inner {
  padding: 0 20px 20px;
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.7;
}

/* ============================================================
   FOOTER
   ============================================================ */
.site-footer {
  background: var(--primary);
  color: rgba(255,255,255,0.7);
  padding: 56px 0 32px;
  margin-top: auto;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.footer-mission {
  font-size: 0.9rem;
  line-height: 1.7;
  margin-bottom: 28px;
  max-width: 800px;
}

.footer-trending-label {
  font-family: var(--font-display);
  font-weight: 600;
  color: rgba(255,255,255,0.9);
  font-size: 0.85rem;
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.footer-trending {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 4px;
  margin-bottom: 28px;
}

.footer-trending a {
  display: inline-block;
  padding: 6px 14px;
  background: rgba(255,255,255,0.06);
  color: rgba(255,255,255,0.7);
  border-radius: 20px;
  font-size: 0.82rem;
  transition: all 0.2s ease;
}

.footer-trending a:hover {
  background: rgba(255,255,255,0.12);
  color: #ffffff;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 20px;
  padding-top: 24px;
  border-top: 1px solid rgba(255,255,255,0.08);
}

.footer-links a {
  color: rgba(255,255,255,0.55);
  font-size: 0.82rem;
  transition: color 0.2s ease;
}

.footer-links a:hover {
  color: #ffffff;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */

/* Tablet */
@media (max-width: 1024px) {
  .articles-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .featured-card {
    grid-template-columns: 1fr;
  }

  .featured-thumb {
    min-height: 200px;
  }

  .curriculum-grid {
    grid-template-columns: 1fr;
  }

  .search-bar {
    flex: 0 1 260px;
  }
}

/* Mobile */
@media (max-width: 768px) {
  .search-bar {
    display: none;
  }

  .header-nav {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .articles-grid {
    grid-template-columns: 1fr;
  }

  .featured-card {
    grid-template-columns: 1fr;
  }

  .featured-thumb {
    min-height: 180px;
  }

  .featured-content {
    padding: 24px 20px;
  }

  .donation-amounts {
    grid-template-columns: repeat(2, 1fr);
  }

  .benefits-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .initiatives-list {
    grid-template-columns: 1fr;
  }

  .achievements-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .curriculum-grid {
    grid-template-columns: 1fr;
  }

  .daily-challenge-links {
    flex-direction: column;
    align-items: center;
  }

  .container {
    padding: 0 16px;
  }

  .logo {
    font-size: 1.15rem;
  }
}

/* Small Mobile */
@media (max-width: 480px) {
  .benefits-grid {
    grid-template-columns: 1fr;
  }

  .achievements-grid {
    grid-template-columns: 1fr;
  }

  .donation-amounts {
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
  }

  .donation-card {
    padding: 24px 16px;
  }

  .achievement-number {
    font-size: 1.75rem;
  }
}

